  "alixpartners-cio-interino":{txt:"A AlixPartners oferece CIO interino e redução de custo de TI para fundos de private equity",num:"",fontes:["peievents-alixpartners"],status:"fraco",tema:"consultorias-2026",uso:["s10","p1.3"],nota:"Página de patrocinador em evento do setor; não reverificada em 29/10/2026."},
  "kpmg-cio-advisory":{txt:"A KPMG vende “CIO Advisory” e serviços de gestão de custos de TI com a Apptio",num:"",fontes:["kpmg-cio-advisory","kpmg-tbm-apptio"],status:"verificado",tema:"consultorias-2026",uso:["s10","p1.5"],nota:"Páginas e materiais da KPMG sobre gestão financeira de TI (TBM): comparação com o mercado e otimização de custos."},
  "ey-oferta-cio":{txt:"A EY organiza a oferta para CIOs em “Technology Strategy & Transformation”, com modelo operacional e finanças de TI",num:"",fontes:["ey-tst-vaga"],status:"a verificar",tema:"consultorias-2026",uso:["s10"],nota:"Inferido de vagas da EY (2025–26); não reverificado."},
