  "ti-lidera-ma-1s25-274":{txt:"Tecnologia da informação liderou as fusões e aquisições do 1º semestre de 2025, com 274 operações",num:"274",fontes:["itforum-ma-1s25"],status:"verificado",tema:"ma-pe",uso:["p3.1"],nota:"KPMG: 739 operações no 1º semestre de 2025. Para 2026, ver o dado da TTR Data.",obs:"Corrige o V5, que atribuía o número ao 1º semestre de 2026."},
  "tecnologia-lidera-ma-1s26":{txt:"Tecnologia e serviços digitais lideraram as fusões e aquisições do 1º semestre de 2026, com 104 transações",num:"104",fontes:["economicnews-ttr-1s26"],status:"verificado",tema:"ma-pe",uso:["s14"],nota:"Dados da TTR Data, com metodologia diferente da KPMG."},
