  "petz-cobasi-26-lojas":{txt:"O órgão de defesa da concorrência (Cade) aprovou a fusão de Petz e Cobasi com a venda de 26 lojas",num:"26",fontes:["moneytimes-petz-cobasi-2025"],status:"verificado",tema:"ma-pe",uso:["s14"],nota:"Dez/2025; as lojas somavam 3,3% do faturamento combinado."},
