  "diligencia-50-mil":{txt:"Diligência com agentes por cerca de US$ 50 mil, contra US$ 500 mil a US$ 1 mi",num:"US$ 50 mil",fontes:["techcrunch-diligencesquared-2026"],status:"fraco",tema:"ma-pe",uso:[],nota:"Número atribuído ao TechCrunch por um blog; não confirmado no texto da reportagem.",obs:"Não usar como número de destaque."},
  "am-assist":{txt:"A Alvarez & Marsal global usa o A&M Assist, agente de IA que lê e resume milhares de páginas em diligências",num:"",fontes:["am-assist-2025"],status:"verificado",tema:"ma-pe",uso:["s14","p3.1"],nota:"Abr/2025; usa modelos da OpenAI."},
  "am-diligencegpt":{txt:"A área de private equity da Alvarez & Marsal criou o DiligenceGPT, plataforma de IA generativa para diligência",num:"",fontes:["am-diligencegpt"],status:"verificado",tema:"ma-pe",uso:["s14","p3.1"],nota:"Jan/2024, pela área Private Equity Performance Improvement da Alvarez & Marsal.",obs:"Escrever o nome da área por extenso, sem a sigla."},
  "pwc-diligencia-ia":{txt:"A PwC vende “AI technology diligence” como oferta própria em transações",num:"",fontes:["pwc-ai-tech-diligence"],status:"verificado",tema:"ma-pe",uso:["s14"],nota:"Página de serviço da PwC EUA."},
