  "bancos-nuvem-3-9-bi":{txt:"Os bancos devem gastar R$ 3,9 bi em migração para a nuvem em 2026, alta de 30%",num:"R$ 3,9 bi",fontes:["febraban-2026"],status:"verificado",tema:"custo-ti-nuvem",uso:["s16","p4.3"],nota:"Eram R$ 3 bi em 2025."},
