  /* ======================= métodos lúdicos (slide 19) ======================= */
  "premortem-metodo":{txt:"No pré-mortem, o time imagina que o projeto já fracassou e lista os motivos antes de começar",num:"",fontes:["hbr-premortem-2007"],status:"verificado",tema:"metodos-ludicos",uso:["s19"],nota:"Gary Klein, Harvard Business Review (set/2007). Cada participante escreve sozinho os motivos; depois o grupo junta a lista e reforça o plano."},
  "premortem-retrospectiva-30":{txt:"Imaginar que um evento já aconteceu aumenta em 30% a capacidade de apontar as razões de um resultado futuro",num:"30%",fontes:["hbr-premortem-2007"],status:"verificado",tema:"metodos-ludicos",uso:["s19"],nota:"Pesquisa de 1989 (Mitchell, Russo e Pennington) citada por Gary Klein no artigo da Harvard Business Review.",obs:"Citar como “pesquisa citada por Gary Klein”."},
  "exercicio-mesa-nist":{txt:"Exercício de mesa é uma discussão guiada por um cenário, em que quem tem papel no plano de TI testa se o plano funciona",num:"",fontes:["nist-sp-800-84"],status:"verificado",tema:"metodos-ludicos",uso:["s19","p4.5"],nota:"Guia SP 800-84 do NIST, o instituto de padrões dos EUA (set/2006): como planejar, conduzir e avaliar testes, treinamentos e exercícios de planos de TI."},
  "jogos-de-guerra-executivos":{txt:"Jogos de guerra ajudam executivos a testar decisões contra a reação de concorrentes quando a incerteza é moderada",num:"",fontes:["mckinsey-war-games-2011"],status:"verificado",tema:"metodos-ludicos",uso:["s19"],nota:"John Horn, McKinsey Quarterly (mar/2011): o valor do jogo depende do desenho e da escolha de quem joga."},
  "dia-1-simulacoes":{txt:"Na preparação do Dia 1 de uma fusão, as equipes fazem sessões de prontidão e simulações nas semanas antes do fechamento",num:"",fontes:["ey-integracao-nove-passos"],status:"verificado",tema:"metodos-ludicos",uso:["s19","p3.3"],nota:"Guia da EY sobre programas de integração (sem data na página)."},
  "dia-1-pontos-de-prontidao":{txt:"A Deloitte recomenda “pontos de prontidão” que testam sob pressão o plano do Dia 1 antes do fechamento",num:"",fontes:["deloitte-day-one"],status:"verificado",tema:"metodos-ludicos",uso:["s19","p3.2"],nota:"Num caso citado, o teste revelou o plano de clonar sistemas sem limpar dados sensíveis de clientes."},
  "jogos-simulacao-aprendizado":{txt:"Treinamentos com jogos de simulação elevaram a confiança em 20% e o conhecimento prático em 14% frente a outros métodos",num:"20%",fontes:["sitzmann-2011"],status:"verificado",tema:"metodos-ludicos",uso:["s19"],nota:"Meta-análise de Traci Sitzmann (Personnel Psychology, 2011): 65 estudos e 6.476 pessoas. Funciona melhor quando o jogo é ativo e faz parte de um programa maior; perde para métodos ativos sem jogo."},

